def get_svg(svg_str, color="currentColor", size=20):
    """Helper to customize SVG string color and size."""
    return svg_str.replace('width="24"', f'width="{size}"') \
                  .replace('height="24"', f'height="{size}"') \
                  .replace('stroke="currentColor"', f'stroke="{color}"')

